<div class="row g-3"><div class="col-lg-4"><div class="km-card p-3"><h4>Nouveau client</h4><form method="post" action="<?=e(base_url('customers'))?>"><?=csrf_field()?><div class="row g-2"><div class="col-6"><input class="form-control" name="first_name" placeholder="Prénom" required></div><div class="col-6"><input class="form-control" name="last_name" placeholder="Nom" required></div></div><input class="form-control mt-2" name="phone" placeholder="Téléphone"><input class="form-control mt-2" type="email" name="email" placeholder="E-mail"><input class="form-control mt-2" name="address" placeholder="Adresse"><select class="form-select mt-2" name="gender"><option value="">Sexe (facultatif)</option><option value="M">M</option><option value="F">F</option><option value="AUTRE">Autre</option></select><button class="btn btn-km mt-3">Ajouter</button></form></div></div><div class="col-lg-8"><div class="km-card p-3"><div class="d-flex justify-content-between"><h4>Clients</h4><form><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Rechercher"></form></div><div class="table-responsive"><table class="table"><thead><tr><th>Client</th><th>Segment</th><th>Achats</th><th>Points</th><th></th></tr></thead><tbody><?php foreach($customers as $c):?><tr><td><strong><?=e($c['first_name'].' '.$c['last_name'])?></strong><div class="small text-muted"><?=e($c['code'].' · '.$c['phone'])?></div></td><td><span class="badge text-bg-light"><?=e($c['segment'])?></span></td><td><?=money($c['total_spent'])?></td><td><?=e($c['points'])?> · <?=e($c['tier'])?></td><td><a class="btn btn-sm btn-outline-dark" href="<?=e(base_url('customers/'.$c['id']))?>">Voir</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div>